  --      name is refused, never read as a match.
  FOR e IN SELECT * FROM jsonb_array_elements(expected) LOOP
    tree := CASE (e->>'doc_type') || ':' || (e->>'agency') || ':' || (e->>'version')
    WHEN 'hde:fda:fda-hde-preparation-v1.0' THEN $pack$[{"key":"administrative","parent_key":null,"label":"Applicant, Humanitarian Use Device Designation and Application","mandatory":false,"path_order":1},{"key":"eligibility","parent_key":null,"label":"Humanitarian Eligibility, Population and Available Alternatives","mandatory":false,"path_order":2},{"key":"device","parent_key":null,"label":"Device Description and Proposed Indications","mandatory":false,"path_order":3},{"key":"benefit_risk","parent_key":null,"label":"Probable Benefit, Risks and Supporting Evidence","mandatory":false,"path_order":4},{"key":"manufacturing","parent_key":null,"label":"Manufacturing and Quality Information","mandatory":false,"path_order":5},{"key":"labeling","parent_key":null,"label":"Humanitarian Device Labeling and Instructions for Use","mandatory":false,"path_order":6},{"key":"clinical","parent_key":null,"label":"Clinical Experience, Investigation Records and Applicable Oversight","mandatory":false,"path_order":7},{"key":"supporting","parent_key":null,"label":"Other Applicable Application Records and References","mandatory":false,"path_order":8}]$pack$::jsonb
    WHEN 'mdl:hc:hc-mdl-preparation-v1.0' THEN $pack$[{"key":"administrative","parent_key":null,"label":"Licence Application, Manufacturer and Device Identifiers","mandatory":false,"path_order":1},{"key":"classification","parent_key":null,"label":"Intended Use, Device Classification and Licence Scope","mandatory":false,"path_order":2},{"key":"device","parent_key":null,"label":"Device Description, Design and Materials","mandatory":false,"path_order":3},{"key":"safety","parent_key":null,"label":"Safety and Effectiveness Requirements and Supporting Evidence","mandatory":false,"path_order":4},{"key":"nonclinical","parent_key":null,"label":"Nonclinical Testing and Verification Evidence","mandatory":false,"path_order":5},{"key":"clinical","parent_key":null,"label":"Clinical Evidence, Benefit-Risk and Evidence Gaps","mandatory":false,"path_order":6},{"key":"manufacturing","parent_key":null,"label":"Manufacturing, Quality System and Applicable Certification","mandatory":false,"path_order":7},{"key":"labeling","parent_key":null,"label":"Canadian Labeling and Instructions for Use","mandatory":false,"path_order":8},{"key":"history","parent_key":null,"label":"Marketing History, Foreign Authorizations and Relevant Changes","mandatory":false,"path_order":9},{"key":"supporting","parent_key":null,"label":"Declarations, References and Class-Specific Supporting Records","mandatory":false,"path_order":10}]$pack$::jsonb
    WHEN 'ivd_licence:hc:hc-ivd-licence-preparation-v1.0' THEN $pack$[{"key":"administrative","parent_key":null,"label":"Licence Application, Manufacturer and Device Identifiers","mandatory":false,"path_order":1},{"key":"classification","parent_key":null,"label":"Intended Use, Device Classification and Licence Scope","mandatory":false,"path_order":2},{"key":"device","parent_key":null,"label":"Device Description, Design and Materials","mandatory":false,"path_order":3},{"key":"safety","parent_key":null,"label":"Safety and Effectiveness Requirements and Supporting Evidence","mandatory":false,"path_order":4},{"key":"nonclinical","parent_key":null,"label":"Nonclinical Testing and Verification Evidence","mandatory":false,"path_order":5},{"key":"clinical","parent_key":null,"label":"Clinical Evidence, Benefit-Risk and Evidence Gaps","mandatory":false,"path_order":6},{"key":"manufacturing","parent_key":null,"label":"Manufacturing, Quality System and Applicable Certification","mandatory":false,"path_order":7},{"key":"labeling","parent_key":null,"label":"Canadian Labeling and Instructions for Use","mandatory":false,"path_order":8},{"key":"history","parent_key":null,"label":"Marketing History, Foreign Authorizations and Relevant Changes","mandatory":false,"path_order":9},{"key":"supporting","parent_key":null,"label":"Declarations, References and Class-Specific Supporting Records","mandatory":false,"path_order":10},{"key":"ivd_performance","parent_key":null,"label":"Assay, Specimen, Analytical and Clinical Performance Evidence","mandatory":false,"path_order":11}]$pack$::jsonb
    WHEN 'shonin:pmda:pmda-shonin-preparation-v1.0' THEN $pack$[{"key":"administrative","parent_key":null,"label":"Japanese Application, Applicant and Marketing Authorization Holder","mandatory":false,"path_order":1},{"key":"classification","parent_key":null,"label":"Device Classification, Intended Use and Approval Route","mandatory":false,"path_order":2},{"key":"device","parent_key":null,"label":"Device Description, Design, Specifications and Principles of Operation","mandatory":false,"path_order":3},{"key":"principles","parent_key":null,"label":"Applicable Essential Principles and Standards Evidence","mandatory":false,"path_order":4},{"key":"evidence","parent_key":null,"label":"Nonclinical, Performance and Clinical Evidence as Applicable","mandatory":false,"path_order":5},{"key":"local_evidence","parent_key":null,"label":"Foreign Evidence Applicability and Documented Japanese Consultation","mandatory":false,"path_order":6},{"key":"manufacturing","parent_key":null,"label":"Manufacturing Sites, Quality System and Conformity Records","mandatory":false,"path_order":7},{"key":"labeling","parent_key":null,"label":"Japanese Labeling, Instructions and Translation Review","mandatory":false,"path_order":8},{"key":"summary","parent_key":null,"label":"Technical Summary, Source References and Unresolved Requirements","mandatory":false,"path_order":9}]$pack$::jsonb
    WHEN 'ninsho:jp_rcb:jp_rcb-ninsho-preparation-v1.0' THEN $pack$[{"key":"administrative","parent_key":null,"label":"Certification Application and Responsible Japanese Entities","mandatory":false,"path_order":1},{"key":"eligibility","parent_key":null,"label":"Device Classification and Certification-Standard Eligibility","mandatory":false,"path_order":2},{"key":"device","parent_key":null,"label":"Device Description, Intended Use and Specifications","mandatory":false,"path_order":3},{"key":"conformity","parent_key":null,"label":"Essential Principles, Certification Standards and Conformity Evidence","mandatory":false,"path_order":4},{"key":"manufacturing","parent_key":null,"label":"Manufacturing and Quality System Conformity","mandatory":false,"path_order":5},{"key":"labeling","parent_key":null,"label":"Japanese Labeling, Instructions and Source References","mandatory":false,"path_order":6},{"key":"questions","parent_key":null,"label":"Certification Body Questions and Unresolved Requirements","mandatory":false,"path_order":7}]$pack$::jsonb
    WHEN 'todokede:pmda:pmda-todokede-preparation-v1.0' THEN $pack$[{"key":"administrative","parent_key":null,"label":"Notification, Device Identifiers and Responsible Japanese Entities","mandatory":false,"path_order":1},{"key":"classification","parent_key":null,"label":"Class I Classification Rationale and Applicable Device Scope","mandatory":false,"path_order":2},{"key":"device","parent_key":null,"label":"Device Description, Intended Use and Specifications","mandatory":false,"path_order":3},{"key":"labeling","parent_key":null,"label":"Japanese Labeling, Instructions and Source Records","mandatory":false,"path_order":4},{"key":"requirements","parent_key":null,"label":"Current Notification Instructions, Supporting Records and Unresolved Requirements","mandatory":false,"path_order":5}]$pack$::jsonb
    WHEN 'ivd_approval:pmda:pmda-ivd-approval-preparation-v1.0' THEN $pack$[{"key":"administrative","parent_key":null,"label":"Japanese Application, Applicant and Marketing Authorization Holder","mandatory":false,"path_order":1},{"key":"classification","parent_key":null,"label":"Device Classification, Intended Use and Approval Route","mandatory":false,"path_order":2},{"key":"device","parent_key":null,"label":"Device Description, Design, Specifications and Principles of Operation","mandatory":false,"path_order":3},{"key":"principles","parent_key":null,"label":"Applicable Essential Principles and Standards Evidence","mandatory":false,"path_order":4},{"key":"evidence","parent_key":null,"label":"Nonclinical, Performance and Clinical Evidence as Applicable","mandatory":false,"path_order":5},{"key":"local_evidence","parent_key":null,"label":"Foreign Evidence Applicability and Documented Japanese Consultation","mandatory":false,"path_order":6},{"key":"manufacturing","parent_key":null,"label":"Manufacturing Sites, Quality System and Conformity Records","mandatory":false,"path_order":7},{"key":"labeling","parent_key":null,"label":"Japanese Labeling, Instructions and Translation Review","mandatory":false,"path_order":8},{"key":"summary","parent_key":null,"label":"Technical Summary, Source References and Unresolved Requirements","mandatory":false,"path_order":9},{"key":"ivd_performance","parent_key":null,"label":"Assay, Specimen, Analytical and Clinical Performance Evidence","mandatory":false,"path_order":10}]$pack$::jsonb
    WHEN 'jp_cdx:pmda:pmda-jp-cdx-preparation-v1.0' THEN $pack$[{"key":"administrative","parent_key":null,"label":"Japanese Application, Applicant and Marketing Authorization Holder","mandatory":false,"path_order":1},{"key":"classification","parent_key":null,"label":"Device Classification, Intended Use and Approval Route","mandatory":false,"path_order":2},{"key":"device","parent_key":null,"label":"Device Description, Design, Specifications and Principles of Operation","mandatory":false,"path_order":3},{"key":"principles","parent_key":null,"label":"Applicable Essential Principles and Standards Evidence","mandatory":false,"path_order":4},{"key":"evidence","parent_key":null,"label":"Nonclinical, Performance and Clinical Evidence as Applicable","mandatory":false,"path_order":5},{"key":"local_evidence","parent_key":null,"label":"Foreign Evidence Applicability and Documented Japanese Consultation","mandatory":false,"path_order":6},{"key":"manufacturing","parent_key":null,"label":"Manufacturing Sites, Quality System and Conformity Records","mandatory":false,"path_order":7},{"key":"labeling","parent_key":null,"label":"Japanese Labeling, Instructions and Translation Review","mandatory":false,"path_order":8},{"key":"summary","parent_key":null,"label":"Technical Summary, Source References and Unresolved Requirements","mandatory":false,"path_order":9},{"key":"ivd_performance","parent_key":null,"label":"Assay, Specimen, Analytical and Clinical Performance Evidence","mandatory":false,"path_order":10},{"key":"paired_product","parent_key":null,"label":"Paired Therapeutic Product, Selection Claim and Co-Development Evidence","mandatory":false,"path_order":11}]$pack$::jsonb
    END;
    SELECT jsonb_array_length(required_sections), required_sections = tree, superseded_by
      INTO n, same, sup
      FROM c2c_rule_packs
     WHERE doc_type = e->>'doc_type' AND agency = e->>'agency' AND version = e->>'version';
    IF NOT FOUND OR n IS DISTINCT FROM (e->>'nodes')::integer OR same IS NOT TRUE THEN
      RAISE EXCEPTION '%:% % must hold this file''s % nodes; found % (tree matches: %)',
        e->>'doc_type', e->>'agency', e->>'version', e->>'nodes',
        coalesce(n::text, 'no row'), coalesce(same::text, 'n/a');
    END IF;
    IF sup IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM c2c_rule_packs
       WHERE doc_type = e->>'doc_type' AND agency = e->>'agency' AND version = sup) THEN
      RAISE EXCEPTION '%:% % is superseded by %, which does not exist',
        e->>'doc_type', e->>'agency', e->>'version', sup;
    END IF;
    SELECT count(*) INTO live FROM c2c_rule_packs
     WHERE doc_type = e->>'doc_type' AND agency = e->>'agency' AND superseded_by IS NULL;
    IF live <> 1 THEN
      RAISE EXCEPTION '%:% must have exactly one live pack; found %', e->>'doc_type', e->>'agency', live;
    END IF;
  END LOOP;
END
$mig$;
